import{_ as d,r as a,o as l,c as n,a as e,b as o,d as s,e as i}from"./chunks/framework.8NMv9ABN.js";const f=JSON.parse('{"title":"Графіки та рисування","description":"","frontmatter":{},"headers":[],"relativePath":"uk/customize/chart-colors.md","filePath":"uk/customize/chart-colors.md"}'),h={name:"uk/customize/chart-colors.md"};function c(b,t,g,k,p,u){const r=a("Screenshot");return l(),n("div",null,[t[0]||(t[0]=e("h1",{id:"графіки-та-рисування",tabindex:"-1"},[o("Графіки та рисування "),e("a",{class:"header-anchor",href:"#графіки-та-рисування","aria-label":'Permalink to "Графіки та рисування"'},"​")],-1)),t[1]||(t[1]=e("p",null,[o("Ці налаштування розташовані у вкладці "),e("strong",null,"Home"),o(" головного вікна, у секції "),e("strong",null,"Charts"),o(". Вони глобальні: їх використовує кожен графік у кожному інструменті — Knives, Alerts, Analyzer, Monitor.")],-1)),s(r,{src:"charts-colors",alt:"Секція налаштувань Charts у вкладці Home",caption:"Home → Charts"}),t[2]||(t[2]=i('<h2 id="палітра" tabindex="-1">Палітра <a class="header-anchor" href="#палітра" aria-label="Permalink to &quot;Палітра&quot;">​</a></h2><p>Кожен колір у Warden — і тут, і в кольорах метрик Monitor, і у вигляді Terminal — відкриває ту саму палітру:</p><ul><li>Квадрат <strong>насиченості / яскравості</strong>, під ним повзунок <strong>відтінку</strong>.</li><li>Повзунок <strong>непрозорості</strong>. Будь-який колір у застосунку можна зробити напівпрозорим.</li><li>Поле <strong>hex</strong>, яке приймає 3, 4, 6 або 8 символів (<code>#f00</code>, <code>#f00a</code>, <code>#ff0000</code>, <code>#ff0000aa</code>), і відсоток поточної непрозорості поруч.</li></ul><p>Зразок, що відкриває палітру, намальований поверх шахової клітинки, тож напівпрозорий колір видно й без відкривання.</p><div class="info custom-block"><p class="custom-block-title">Де зберігається непрозорість</p><p>У більшості місць — кольори свічок, колір рисунків і всі кольори метрик Monitor — <strong>непрозорість є частиною значення hex</strong>. При повній непрозорості це звичайний 6-символьний hex; щойно опускаєте нижче 100%, він стає 8-символьним <code>#rrggbbaa</code>.</p><p>Виняток — згруповані кольори вигляду Terminal: там колір і його непрозорість зберігаються двома окремими значеннями, тому в тій панелі поруч із кожним записом показано відсоток.</p></div><h2 id="кольори-свічок" tabindex="-1">Кольори свічок <a class="header-anchor" href="#кольори-свічок" aria-label="Permalink to &quot;Кольори свічок&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Налаштування</th><th>Що робить</th><th>За замовчуванням</th></tr></thead><tbody><tr><td><strong>Bullish candle</strong></td><td>Колір свічок, що закрилися вгору</td><td><code>#9D9D9D</code>, повністю непрозорий</td></tr><tr><td><strong>Bearish candle</strong></td><td>Колір свічок, що закрилися вниз</td><td><code>#4A4A4A</code>, повністю непрозорий</td></tr></tbody></table><p>Обидва відкривають палітру. Зміна одразу застосовується до всіх графіків у застосунку, тож обрана тут схема свічок супроводжує вас від мініатюри в Knives до повноекранної панелі в Analyzer.</p><p>Типові кольори навмисно нейтрально-сірі, а не зелено-червоні: задум у тому, щоб колір в інтерфейсі означав «щось перетнуло поріг», а не «ціна пішла вгору». Якщо вам звичніші класичні зелені й червоні свічки — задайте їх тут.</p><h2 id="колір-рисунків" tabindex="-1">Колір рисунків <a class="header-anchor" href="#колір-рисунків" aria-label="Permalink to &quot;Колір рисунків&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Налаштування</th><th>Що робить</th><th>За замовчуванням</th></tr></thead><tbody><tr><td><strong>Drawing color</strong></td><td>Колір усіх п&#39;яти інструментів рисування</td><td>Успадковує акцентний колір</td></tr></tbody></table><p>Один колір діє на всі інструменти рисування. Якщо ви його ніколи не змінювали, він слідує за акцентним кольором, обраним у вкладці Home; щойно ви задасте його явно, він перестає стежити за акцентом і лишається таким, як ви поставили.</p><h2 id="інструменти-рисування" tabindex="-1">Інструменти рисування <a class="header-anchor" href="#інструменти-рисування" aria-label="Permalink to &quot;Інструменти рисування&quot;">​</a></h2><p>Графіки в <a href="/manual/uk/tools/analyzer.html">Analyzer</a> та в повноекранних виглядах підтримують п&#39;ять інструментів рисування. Кожен прив&#39;язаний до однієї клавіші, і кожну прив&#39;язку можна змінити тут.</p><table tabindex="0"><thead><tr><th>Інструмент</th><th>Що малює</th><th>Клавіша за замовчуванням</th></tr></thead><tbody><tr><td><strong>Horizontal ray key</strong></td><td>Горизонтальний промінь на обраній ціні</td><td><kbd>H</kbd></td></tr><tr><td><strong>Trend line key</strong></td><td>Лінію тренду по двох точках</td><td><kbd>T</kbd></td></tr><tr><td><strong>Rectangle key</strong></td><td>Прямокутник / область</td><td><kbd>B</kbd></td></tr><tr><td><strong>Pencil key</strong></td><td>Вільне малювання</td><td><kbd>P</kbd></td></tr><tr><td><strong>Dissolving pencil key</strong></td><td>Вільне малювання, яке саме зникає</td><td><kbd>F</kbd></td></tr></tbody></table><p>Щоб перепризначити, клацніть кнопку клавіші поруч — вона перемкнеться на <code>Press a key…</code> — і натисніть потрібну клавішу. <kbd>Esc</kbd> скасовує без змін.</p><p>Кілька правил, які застосовує захоплення клавіш:</p><ul><li>Для п&#39;яти інструментів рисування приймаються лише літери й цифри.</li><li>Комбінації з модифікаторами відхиляються — натискання <kbd>Ctrl</kbd>+<kbd>H</kbd> нічого не дасть, прив&#39;язка має бути голою клавішею.</li><li>Прив&#39;язки мають бути унікальними. Якщо обрати клавішу, вже призначену іншому інструменту, захоплення скасовується й нічого не змінюється.</li></ul><p>Прив&#39;язки зберігаються як фізичні позиції клавіш, а не символи, тож вони продовжують працювати після зміни розкладки чи набору іншою мовою.</p><p>Рисунки зберігаються для кожного символу <em>і</em> для кожної біржі, тож перемикання графіка з Bybit на Binance для того самого тікера покаже інший набір рисунків.</p><h2 id="магніт" tabindex="-1">Магніт <a class="header-anchor" href="#магніт" aria-label="Permalink to &quot;Магніт&quot;">​</a></h2><p>Магніт прив&#39;язує точку, яку ви ставите, до найближчого максимуму або мінімуму свічки, щоб промені й лінії тренду лягали точно на тінь, а не поруч із нею.</p><table tabindex="0"><thead><tr><th>Налаштування</th><th>Що робить</th><th>За замовчуванням</th></tr></thead><tbody><tr><td><strong>Magnet</strong> режим</td><td><code>Hold</code> або <code>Toggle</code></td><td><code>Hold</code></td></tr><tr><td><strong>Magnet</strong> клавіша</td><td>Клавіша, що вмикає його</td><td><kbd>Ctrl</kbd> (лівий)</td></tr></tbody></table><p>Два режими:</p><ul><li><strong>Hold</strong> — магніт активний лише поки клавіша натиснута. Миттєвий.</li><li><strong>Toggle</strong> — натискання вмикає магніт, повторне натискання вимикає. Стан зберігається між перезапусками.</li></ul><p>На відміну від інструментів рисування, клавішею магніта <strong>може</strong> бути голий модифікатор — <kbd>Ctrl</kbd>, <kbd>Shift</kbd>, <kbd>Alt</kbd> чи <kbd>Meta</kbd> — а також літера або цифра. За замовчуванням це лівий <kbd>Ctrl</kbd>. Те саме правило про відсутність дублікатів діє і щодо п&#39;яти клавіш рисування.</p><h2 id="чого-тут-немає" tabindex="-1">Чого тут немає <a class="header-anchor" href="#чого-тут-немає" aria-label="Permalink to &quot;Чого тут немає&quot;">​</a></h2><p>Кольори, які показують перетин порогу метрикою, налаштовуються в самих інструментах, а не глобально — бо самі пороги теж належать інструментам:</p><ul><li>Кольори рівнів NATR і % Change у Monitor, контури й заливки → <a href="/manual/uk/tools/monitor.html#metric-colors">Monitor → Metric colors</a></li><li>Кольори драбини, смуг глибини та позицій у Terminal → <a href="/manual/uk/tools/terminal.html#вигляд">Terminal → Вигляд</a></li></ul>',29))])}const y=d(h,[["render",c]]);export{f as __pageData,y as default};
